    try:
        conn = ConnectHandler(**params)
        result = {}
        cmds = [
            ("config", "show configuration commands"),
            ("interfaces", "show interfaces"),
            ("ospf_neighbors", "show ip ospf neighbor"),
            ("ospf_routes", "show ip ospf route"),
            ("routes", "show ip route"),
            ("frr", "vtysh -c 'show running-config'"),
        ]
        if name == "HQ-Edge":
            cmds += [
                ("bgp_summary", "show ip bgp summary"),
                ("bgp_routes", "show ip bgp"),
                ("bgp_neighbors_a", "show ip bgp neighbors 203.0.113.1 received-routes"),
                ("bgp_neighbors_b", "show ip bgp neighbors 203.0.113.5 received-routes"),
                ("bgp_advertised_a", "show ip bgp neighbors 203.0.113.1 advertised-routes"),
                ("bgp_advertised_b", "show ip bgp neighbors 203.0.113.5 advertised-routes"),
                ("nat", "show nat source rules"),
                ("route_maps", "vtysh -c 'show route-map'"),
            ]
        if name in ("Hub-A", "Hub-B"):
            cmds += [
                ("ospf_database", "show ip ospf database"),
                ("ospf_vlink", "show ip ospf virtual-links"),
            ]
        for key, cmd in cmds:
            try:
                result[key] = conn.send_command(cmd, read_timeout=30)
            except Exception as e:
                result[key] = f"ERROR: {e}"
        conn.disconnect()
        return name, result
    except Exception as e:
        return name, {"error": str(e)}

def collect_mikrotik(name, params):
    try:
        conn = ConnectHandler(**params)
        result = {}
        cmds = [
            ("export", "/export terse"),
            ("ospf_neighbors", "/routing ospf neighbor print detail"),
            ("routes", "/ip route print detail"),
            ("addresses", "/ip address print detail"),
            ("ospf_instance", "/routing ospf instance print detail"),
            ("ospf_area", "/routing ospf area print detail"),
            ("ospf_interface", "/routing ospf interface-template print detail"),
            ("firewall_filter", "/ip firewall filter print detail"),
        ]
        for key, cmd in cmds:
            try:
                result[key] = conn.send_command(cmd, read_timeout=30)
            except Exception as e:
                result[key] = f"ERROR: {e}"
        conn.disconnect()
        return name, result
    except Exception as e:
        return name, {"error": str(e)}

def collect_linux(name, params):
    try:
        conn = ConnectHandler(**params)
        result = {}
        cmds = [
            ("ip_addr", "ip addr show"),
            ("ip_route", "ip route show"),
            ("interfaces_file", "cat /etc/network/interfaces"),
        ]
        for key, cmd in cmds:
            try:
                result[key] = conn.send_command(cmd, read_timeout=15)
            except Exception as e:
                result[key] = f"ERROR: {e}"
        conn.disconnect()
        return name, result
    except Exception as e:
        return name, {"error": str(e)}

def main():
    results = {}
    with ThreadPoolExecutor(max_workers=19) as pool:
        futures = []
        for name, params in VYOS_DEVICES.items():
            futures.append(pool.submit(collect_vyos, name, params))
        for name, params in MIKROTIK_DEVICES.items():
            futures.append(pool.submit(collect_mikrotik, name, params))
        for name, params in LINUX_HOSTS.items():
            futures.append(pool.submit(collect_linux, name, params))
        for f in as_completed(futures):
            name, data = f.result()
            results[name] = data
            print(f"  collected {name}")

    with open("state.json", "w") as f:
        json.dump(results, f, indent=2)
    print("Done. State saved to state.json")

if __name__ == "__main__":
    main()

